--
-- Table structure for table `cf_asientos`
--

DROP TABLE IF EXISTS `cf_asientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cf_asientos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `numero` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha` date NOT NULL,
  `descripcion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `tipo` enum('AUTOMATICO','MANUAL','AJUSTE','CIERRE') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'AUTOMATICO',
  `origen_modulo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `origen_id` int DEFAULT NULL,
  `periodo_id` int DEFAULT NULL,
  `estado` enum('BORRADOR','APROBADO','ANULADO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'BORRADOR',
  `creado_por` int DEFAULT NULL,
  `aprobado_por` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `numero` (`numero`),
