DROP TABLE IF EXISTS `notificaciones_alertas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notificaciones_alertas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `usuario_id` int DEFAULT NULL,
  `titulo` varchar(200) DEFAULT NULL,
  `mensaje` text,
  `tipo_alerta` enum('info','advertencia','error','exito') NOT NULL DEFAULT 'info',
  `leida` tinyint(1) NOT NULL DEFAULT '0',
  `fecha_creacion` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_lectura` timestamp NULL DEFAULT NULL,
  `accion_asociada` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_leida` (`leida`),
  KEY `idx_usuario_id` (`usuario_id`),
  CONSTRAINT `notificaciones_alertas_ibfk_1` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
