--
-- Table structure for table `pagos`
--

DROP TABLE IF EXISTS `pagos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pagos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `numero_referencia` varchar(50) NOT NULL,
  `numero_recibo` varchar(30) DEFAULT NULL,
  `numero_ncf` varchar(20) DEFAULT NULL,
  `tipo_comprobante` enum('B01','B02','B14','B15') DEFAULT 'B02',
  `poliza_id` int NOT NULL,
  `cliente_id` int NOT NULL,
  `monto` decimal(15,2) DEFAULT NULL,
  `fecha_pago` date DEFAULT NULL,
  `tipo_pago` enum('efectivo','transferencia','cheque','tarjeta_credito','tarjeta_debito') NOT NULL,
  `numero_comprobante` varchar(100) DEFAULT NULL,
  `banco` varchar(100) DEFAULT NULL,
  `estado_pago` enum('pendiente','procesado','rechazado','reembolsado') NOT NULL DEFAULT 'pendiente',
  `registrado_por` int DEFAULT NULL,
  `validado_por` int DEFAULT NULL,
  `fecha_registro` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_validacion` timestamp NULL DEFAULT NULL,
  `fecha_modificacion` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `itbis_pago` decimal(15,2) DEFAULT '0.00',
  `descripcion` varchar(255) DEFAULT NULL,
  `cuota_numero` int DEFAULT '1',
  `cuota_total` int DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `numero_referencia` (`numero_referencia`),
  KEY `poliza_id` (`poliza_id`),
  KEY `cliente_id` (`cliente_id`),
  KEY `registrado_por` (`registrado_por`),
  KEY `validado_por` (`validado_por`),
  KEY `idx_estado_pago` (`estado_pago`),
  KEY `idx_fecha_pago` (`fecha_pago`),
  CONSTRAINT `pagos_ibfk_1` FOREIGN KEY (`poliza_id`) REFERENCES `polizas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pagos_ibfk_2` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pagos_ibfk_3` FOREIGN KEY (`registrado_por`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pagos_ibfk_4` FOREIGN KEY (`validado_por`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
