INSERT INTO `reglas_negocio` VALUES (1,'LIM_DESC_MAX','Límite de Descuento Máximo','descuento',NULL,'Porcentaje de descuento máximo que un agente comercial puede aplicar sin requerir aprobación (ej. 15%).',NULL,'15','activo','2026-06-27 16:25:50',NULL),(2,'EDAD_MIN_COND','Edad Mínima de Conductor','vehiculo',NULL,'Edad mínima del conductor permitida para emitir un seguro de vehículo.',NULL,'18','activo','2026-06-27 16:25:50',NULL),(3,'ANTIG_MAX_VEH','Antigüedad Máxima del Vehículo','vehiculo',NULL,'Cantidad máxima de años de antigüedad permitida para un vehículo en seguros de ley.',NULL,'20','activo','2026-06-27 16:25:50',NULL),(4,'RECAR_USO_COM','Recargo por Uso Comercial','emision',NULL,'Porcentaje de recargo aplicado sobre la prima neta para vehículos de uso comercial (ej. 10%).',NULL,'10','activo','2026-06-27 16:25:50',NULL),(5,'TASA_COM_MAX','Comisión Máxima de Agente','comision',NULL,'Porcentaje máximo de comisión permitido por defecto para un agente comercial.',NULL,'25','activo','2026-06-27 16:25:50',NULL),(11,'VAL_DOC_CEDULA_UNICIDAD','Unicidad de C├®dula Dominicana (Mod 10)','documentos','[\"clientes\",\"cotizaciones\",\"usuarios\"]','Exige que cada n├║mero de C├®dula Dominicana sea ├║nico por persona/cliente en toda la plataforma (Norma 4-VAF).','Garantiza la trazabilidad ├║nica de la persona natural seg├║n est├índares JCE/DGII.','UNICO_STRICT','activo','2026-07-20 07:25:02',NULL),(12,'VAL_DOC_RNC_UNICIDAD','Unicidad de RNC Comercial (Mod 11 DGII)','documentos','[\"clientes\",\"cotizaciones\",\"fianzas\"]','Garantiza que el Registro Nacional de Contribuyentes (RNC) sea exclusivo por persona jur├¡dica.','Evita duplicaci├│n fiscal y falsificaci├│n de identidades comerciales.','UNICO_STRICT','activo','2026-07-20 07:25:02',NULL),(13,'VAL_DOC_PASAPORTE_UNICIDAD','Unicidad de Pasaporte (Internacional / RD)','documentos','[\"clientes\",\"cotizaciones\"]','Verifica que los pasaportes extranjeros o nacionales no se repitan entre clientes diferentes.','Norma NOFTRAB de identificaci├│n de extranjeros.','UNICO_STRICT','activo','2026-07-20 07:25:02',NULL),(14,'VAL_DOC_LICENCIA_UNICIDAD','Unicidad de Licencia de Conducir','documentos','[\"cotizaciones\",\"vehiculos\"]','Verifica que la licencia de conducir registrada sea ├║nica por conductor afianzado/asegurado.','Est├índar INTRANT / Superintendencia de Seguros.','UNICO_STRICT','activo','2026-07-20 07:25:02',NULL),(15,'VAL_VEH_CHASIS_UNICIDAD','Unicidad de Chasis / VIN de Veh├¡culo','vehiculos','[\"cotizaciones\",\"polizas\",\"vehiculos\"]','Impide la duplicidad del n├║mero de Chasis/VIN en p├│lizas de Seguro de Ley activas o procesadas.','Evita doble aseguramiento y fraude de veh├¡culos robados o clonados.','UNICO_STRICT','activo','2026-07-20 07:25:02',NULL),(16,'VAL_VEH_PLACA_UNICIDAD','Unicidad de Placa de Veh├¡culo','vehiculos','[\"cotizaciones\",\"polizas\"]','Impide que una misma Placa de veh├¡culo sea utilizada en dos cotizaciones/p├│lizas vigentes de clientes distintos.','Est├índar DGII de circulaci├│n de motorizados.','UNICO_STRICT','activo','2026-07-20 07:25:02',NULL),(17,'VAL_FIANZA_NUMERO_UNICIDAD','Unicidad de N├║mero de Fianza','fianzas','[\"fianzas\",\"polizas\"]','Exige que cada n├║mero de Fianza emitido o procesado sea ├║nico e irrepetible en el sistema.','Cumplimiento estricto con la Ley 146-02 sobre seguros y fianzas de la Rep├║blica Dominicana.','UNICO_STRICT','activo','2026-07-20 07:25:02',NULL);
