--
-- Table structure for table `siniestros`
--

DROP TABLE IF EXISTS `siniestros`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `siniestros` (
  `id` int NOT NULL AUTO_INCREMENT,
  `numero_siniestro` varchar(30) NOT NULL,
  `poliza_id` int NOT NULL,
  `cliente_id` int NOT NULL,
  `fecha_siniestro` date NOT NULL,
  `descripcion_evento` text NOT NULL,
  `lugar_evento` text,
  `monto_reclamado` decimal(15,2) DEFAULT NULL,
  `monto_aprobado` decimal(15,2) DEFAULT NULL,
  `estado` enum('registrado','en_revision','aprobado','rechazado','pagado') NOT NULL DEFAULT 'registrado',
  `evidencia_adjunta` varchar(255) DEFAULT NULL,
  `registrado_por` int DEFAULT NULL,
  `revisado_por` int DEFAULT NULL,
  `aprobado_por` int DEFAULT NULL,
  `fecha_registro` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_revision` timestamp NULL DEFAULT NULL,
  `fecha_aprobacion` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `numero_siniestro` (`numero_siniestro`),
  KEY `poliza_id` (`poliza_id`),
  KEY `cliente_id` (`cliente_id`),
  KEY `registrado_por` (`registrado_por`),
  KEY `revisado_por` (`revisado_por`),
  KEY `aprobado_por` (`aprobado_por`),
  KEY `idx_numero_siniestro` (`numero_siniestro`),
  KEY `idx_estado` (`estado`),
  KEY `idx_fecha_siniestro` (`fecha_siniestro`),
  CONSTRAINT `siniestros_ibfk_1` FOREIGN KEY (`poliza_id`) REFERENCES `polizas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `siniestros_ibfk_2` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `siniestros_ibfk_3` FOREIGN KEY (`registrado_por`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL,
  CONSTRAINT `siniestros_ibfk_4` FOREIGN KEY (`revisado_por`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL,
  CONSTRAINT `siniestros_ibfk_5` FOREIGN KEY (`aprobado_por`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

